import type { KeyboardEvent } from "react";
import "./StatusMessage.css";

export interface StatusMessageProps {
  text: string;
  onDismiss: () => void;
}

export function StatusMessage({ text, onDismiss }: StatusMessageProps) {
  // Escape dismisses the message while focus is inside it.
  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key === "Escape") {
      event.stopPropagation();
      onDismiss();
    }
  };

  // The live region stays mounted so screen readers reliably announce
  // content inserted into it. Only the visible message is conditional.
  return (
    <div className="status-message-region" role="status" aria-live="polite" aria-atomic="true">
      {text && (
        <div className="status-message" onKeyDown={handleKeyDown}>
          <p className="status-message__text">{text}</p>
          <button type="button" className="status-message__dismiss" onClick={onDismiss}>
            Dismiss
          </button>
        </div>
      )}
    </div>
  );
}
