.status-message {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  box-sizing: border-box;
  width: 100%;
  max-width: 32rem;
  padding: 0.75rem 1rem;
  border: 1px solid var(--status-muted-border);
  border-radius: 0.5rem;
  background: var(--status-bg);
  color: var(--status-fg);
  box-shadow: var(--status-shadow);
  font-family: inherit;
  animation: status-message-in 180ms ease-out;
}

.status-message__text {
  margin: 0;
  font-size: 0.95rem;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.status-message__dismiss {
  flex-shrink: 0;
  padding: 0.35rem 0.75rem;
  border: 1px solid var(--status-muted-border);
  border-radius: 0.375rem;
  background: var(--status-button-bg);
  color: var(--status-button-fg);
  font: inherit;
  font-size: 0.875rem;
  cursor: pointer;
}

.status-message__dismiss:hover {
  background: var(--status-button-hover);
}

.status-message__dismiss:focus-visible,
.status-message:focus-visible {
  outline: 2px solid var(--status-focus);
  outline-offset: 2px;
}

@keyframes status-message-in {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .status-message {
    animation: none;
  }
}
